use vstd::prelude::*;

verus! {

fn empty(n: u8) -> (result: Vec<f64>)
    ensures
        result@.len() == n as nat,
{
    let mut v: Vec<f64> = Vec::new();

    while v.len() < n as usize
        invariant
            v@.len() <= n as nat,
        decreases
            (n as nat) - v@.len(),
    {
        // No requirements on the stored values; any f64 is fine.
        v.push(0.0);

        // Helpful facts for the verifier:
        assert(v@.len() <= n as nat);
    }

    // At loop exit: v.len() >= n and invariant gives v.len() <= n, so equality.
    assert(!(v.len() < n as usize));
    assert(v@.len() == n as nat);

    v
}

} // verus!

